insert into public.recipes (id,name,description,cuisine,preparation_time,difficulty,servings,calories,protein,carbohydrates,fat,ingredients,instructions,tags,allergens,palette) values ('egg-fried-rice','High-Protein Egg Fried Rice','Leftover rice, eggs and a handful of greens turned into a 15-minute dinner.','Asian',15,'Easy',1,480,22,62,15,'[{"name":"Cooked rice","key":"rice","amount":1,"unit":"cup","category":"Grains","cost":0.4},{"name":"Eggs","key":"egg","amount":2,"unit":"pcs","category":"Eggs","cost":0.6},{"name":"Frozen peas","key":"peas","amount":0.5,"unit":"cup","category":"Frozen Food","cost":0.4,"optional":true},{"name":"Spinach","key":"spinach","amount":1,"unit":"cup","category":"Vegetables","cost":0.5,"optional":true},{"name":"Soy sauce","key":"soy sauce","amount":1,"unit":"tbsp","category":"Other","cost":0.1}]'::jsonb,'[{"text":"Heat a pan with a little oil over medium-high heat."},{"text":"Scramble the eggs until just set, then push them to the side.","timer_seconds":120},{"text":"Add the rice and peas and stir-fry until hot.","timer_seconds":240},{"text":"Stir in the spinach and soy sauce, mix with the eggs and serve."}]'::jsonb,array['high-protein','quick','budget']::text[],array['eggs','soy']::text[],array['#F2C94C','#8BCFB0']::text[]) on conflict (id) do update set name = excluded.name, ingredients = excluded.ingredients, instructions = excluded.instructions;
