insert into public.recipes (id,name,description,cuisine,preparation_time,difficulty,servings,calories,protein,carbohydrates,fat,ingredients,instructions,tags,allergens,palette) values ('vegetable-omelette','Vegetable Omelette','Three eggs with whatever vegetables need using up.','French',12,'Easy',1,360,25,7,26,'[{"name":"Eggs","key":"egg","amount":3,"unit":"pcs","category":"Eggs","cost":0.9},{"name":"Spinach","key":"spinach","amount":1,"unit":"cup","category":"Vegetables","cost":0.5},{"name":"Tomato","key":"tomato","amount":1,"unit":"pcs","category":"Vegetables","cost":0.4},{"name":"Cheese","key":"cheese","amount":20,"unit":"g","category":"Dairy","cost":0.4},{"name":"Bell pepper","key":"bell pepper","amount":0.5,"unit":"pcs","category":"Vegetables","cost":0.5,"optional":true}]'::jsonb,'[{"text":"Whisk the eggs with a pinch of salt."},{"text":"Chop the vegetables and soften them in a pan for two minutes."},{"text":"Pour in the eggs and cook on medium-low until almost set.","timer_seconds":180},{"text":"Add the cheese, fold the omelette in half and serve."}]'::jsonb,array['high-protein','quick','vegetarian','healthy','few-ingredients']::text[],array['eggs','dairy']::text[],array['#F2C94C','#EF8A6F']::text[]) on conflict (id) do update set name = excluded.name, ingredients = excluded.ingredients, instructions = excluded.instructions;
insert into public.recipes (id,name,description,cuisine,preparation_time,difficulty,servings,calories,protein,carbohydrates,fat,ingredients,instructions,tags,allergens,palette) values ('spinach-chicken-omelette','Spinach and Chicken Omelette','Uses up spinach and leftover chicken. 38 g of protein.','American',15,'Easy',1,420,38,4,27,'[{"name":"Eggs","key":"egg","amount":3,"unit":"pcs","category":"Eggs","cost":0.9},{"name":"Chicken breast","key":"chicken breast","amount":60,"unit":"g","category":"Meat","cost":0.8},{"name":"Spinach","key":"spinach","amount":1,"unit":"cup","category":"Vegetables","cost":0.5},{"name":"Cheese","key":"cheese","amount":15,"unit":"g","category":"Dairy","cost":0.3,"optional":true}]'::jsonb,'[{"text":"Dice the chicken and cook it in a pan until hot all the way through.","timer_seconds":300},{"text":"Add the spinach and stir until it wilts."},{"text":"Pour over the whisked eggs and cook until set.","timer_seconds":180},{"text":"Sprinkle with cheese, fold and serve."}]'::jsonb,array['high-protein','quick','few-ingredients']::text[],array['eggs','dairy']::text[],array['#8BCFB0','#F2C94C']::text[]) on conflict (id) do update set name = excluded.name, ingredients = excluded.ingredients, instructions = excluded.instructions;
